  white-space: pre-wrap;
  word-break: break-word;
  background: #161b22;
  border: 1px solid #30363d;
  border-radius: 8px;
  padding: 12px;
  overflow-x: auto;
  font-size: 0.85rem;
}
footer { border-top: 1px solid #30363d; padding-top: 14px; color: #8b949e; font-size: 0.85rem; }
